# ------------------------------------------------------------------ BA-07
ders("BA-07", "BA", "BABOK v3 kavramları · İş İngilizcesi", 7, "İş analizi 7: Test ve canlıya geçiş",
 "kıdemli iş analisti dizisi", "Kullanıcı kabul testi, hatalar ve canlıya geçiş.",
 ["am_michael", "bf_emma"], "am_michael", [
 K("user acceptance testing", "kullanıcı kabul testi.", "User acceptance testing starts next Monday.", "Kullanıcı kabul testi önümüzdeki pazartesi başlıyor."),
 K("test case", "test senaryosu, test durumu.", "We wrote forty test cases for the new screen.", "Yeni ekran için kırk test senaryosu yazdık."),
 K("test scenario", "test senaryosu (geniş).", "Each test scenario covers a real business situation.", "Her test senaryosu gerçek bir iş durumunu kapsıyor."),
 K("defect", "hata, kusur.", "We found twelve defects during testing.", "Test sırasında on iki hata bulduk."),
 K("severity", "önem derecesi.", "This defect has high severity.", "Bu hatanın önem derecesi yüksek."),
 K("regression testing", "gerileme testi.", "After the fix, we need regression testing.", "Düzeltmeden sonra gerileme testine ihtiyacımız var."),
 K("release", "sürüm; yayımlamak.", "The next release is planned for June.", "Bir sonraki sürüm haziran için planlandı."),
 K("go-live", "canlıya geçiş.", "The go-live date is the first of July.", "Canlıya geçiş tarihi bir temmuz."),
 K("rollback", "geri alma.", "If something goes wrong, we have a rollback plan.", "Bir şey ters giderse geri alma planımız var."),
 K("cutover", "geçiş (eski sistemden yeniye).", "The cutover will happen over the weekend.", "Geçiş hafta sonu yapılacak."),
 K("hypercare", "canlı sonrası yoğun destek.", "During hypercare, the project team supports users directly.", "Canlı sonrası yoğun destek döneminde proje ekibi kullanıcılara doğrudan destek veriyor."),
 K("lessons learned", "çıkarılan dersler.", "We'll hold a lessons learned session after go-live.", "Canlıya geçişten sonra çıkarılan dersler toplantısı yapacağız."),
 ], [P("Is it a blocker?", "Engelleyici mi?"), P("Can we go live with this?", "Bununla canlıya geçebilir miyiz?"),
     P("What's the workaround?", "Geçici çözüm ne?"), P("We're on track.", "Planlandığı gibi ilerliyoruz.")],
 "Şimdi canlıya geçişten bir hafta önce yapılan bir hazırlık toplantısını dinleyeceksiniz.",
 ["PM|Go-live is next Saturday. Where are we with user acceptance testing?",
  "BA|We've run ninety percent of the test cases. Business users have signed off on most test scenarios.",
  "PM|How many open defects?", "BA|Seven. Five are low severity, and they have workarounds.",
  "PM|And the other two?", "BA|One is high severity. Customers can't upload documents larger than five megabytes. The developers have a fix, but we need regression testing.",
  "QA|We can finish regression testing by Wednesday.", "PM|Good. Then it's not a blocker for the release, as long as the fix passes.",
  "BA|For the cutover, the old system will be closed on Friday night. If anything goes wrong, we have a rollback plan.",
  "PM|And after go-live?", "BA|Two weeks of hypercare. The project team will sit with the users. Then we'll hold a lessons learned session."],
 [Q("How many open defects are there?", "Seven."),
  Q("What is the high-severity defect?", "Customers can't upload documents larger than five megabytes."),
  Q("How long is the hypercare period?", "Two weeks.")],
 [konusma("Toplantı simülasyonu", ["Şimdi bir toplantı simülasyonu. Sponsor, iki ciddi hata olmasına rağmen canlıya geçmek istiyor.",
                                   "Riski açıklayıp kibarca bir seçenek önerin. On beş saniyeniz var."],
          "We can't delay the go-live. Let's just launch and fix the bugs later.",
          ["I understand the pressure on the date.", "But these two defects affect real customers, so the risk is high.",
           "Could we launch on time with a workaround for one, and delay only the feature with the second defect?"], 15),
  konusma("Mülakat köşesi", MULAKAT, "What is your role during user acceptance testing?",
          ["I usually prepare the test scenarios with business users, based on the requirements and the acceptance criteria.",
           "During testing, I help users log defects clearly and agree on their severity with the team.",
           "I also make sure that every requirement is covered, so that the sign-off is meaningful.",
           "After go-live, I support users during hypercare and collect lessons learned."])],
 konusmacilar={"PM": "bf_emma", "BA": "am_michael", "QA": "af_heart"},
 dinleme_en=["Many projects treat go-live as the finish line.", "In reality, it is the start of a new phase.",
             "The first weeks after launch reveal problems that testing missed, because real users behave differently from testers.",
             "That's why a hypercare period is so valuable.", "And a short, honest lessons learned session helps the next project avoid the same mistakes."],
 dinleme_en_sesi="bf_emma"),

