ders("C1-07", "C1", "Oxford 5000 · C1 · IELTS konusu: teknoloji etiği", 7, "Teknoloji ve etik",
 "C1 seviyesi", "Yapay zekâ, gözetim ve teknoloji etiği. IELTS yazma ve konuşma sınavlarında giderek daha sık çıkan bir konu.",
 ["bf_emma", "am_michael"], "bm_lewis", [
 K("ethical", "etik, ahlaki.", "Is it ethical to test products on animals?", "Ürünleri hayvanlar üzerinde test etmek etik mi?"),
 K("consent", "onay, rıza.", "Data can't be shared without the user's consent.", "Veriler kullanıcının onayı olmadan paylaşılamaz."),
 K("surveillance", "gözetim.", "Mass surveillance raises serious concerns.", "Kitlesel gözetim ciddi endişelere yol açıyor."),
 K("autonomous", "özerk, kendi kendine işleyen.", "Autonomous cars could reduce accidents.", "Sürücüsüz arabalar kazaları azaltabilir."),
 K("algorithm", "algoritma.", "The algorithm decides which posts you see.", "Hangi gönderileri göreceğinize algoritma karar veriyor."),
 K("accountability", "hesap verebilirlik.", "Who has accountability if an AI system makes a mistake?", "Bir yapay zekâ sistemi hata yaparsa hesabını kim verir?"),
 K("transparency", "şeffaflık.", "Companies should offer more transparency about how they use data.", "Şirketler verileri nasıl kullandıkları konusunda daha şeffaf olmalı."),
 K("safeguard", "güvence, koruma önlemi; korumak.", "We need strong safeguards for children online.", "Çocuklar için internette güçlü koruma önlemlerine ihtiyacımız var."),
 K("unintended", "istenmeyen, kasıtsız.", "The policy had unintended consequences.", "Politikanın istenmeyen sonuçları oldu."),
 K("dilemma", "ikilem.", "Doctors often face difficult ethical dilemmas.", "Doktorlar sık sık zor etik ikilemlerle karşılaşır."),
 K("genetic modification", "genetik değişiklik.", "Genetic modification can make crops resistant to disease.", "Genetik değişiklik ekinleri hastalıklara dayanıklı hâle getirebilir."),
 K("misuse", "kötüye kullanmak; kötüye kullanım.", "Personal data can easily be misused.", "Kişisel veriler kolayca kötüye kullanılabilir."),
 ], [P("raise ethical concerns", "etik kaygılara yol açmak."), P("without consent", "onay olmadan."),
     P("unintended consequences", "istenmeyen sonuçlar."), P("hold someone accountable", "birini sorumlu tutmak.")],
 "Şimdi yapay zekâ ve etik üzerine bir panelden kısa bir bölüm dinleyeceksiniz.",
 ["MOD|Algorithms now decide who gets a loan, a job interview, or even parole. Should we be worried?",
  "P1|We should be careful. These systems learn from past data, and if that data is biased, the algorithm can repeat the bias, often in unintended ways.",
  "MOD|So who has accountability when it goes wrong?", "P1|That's the real dilemma. The developer, the company and the user may all blame each other.",
  "P2|That's why transparency matters. People have a right to know when an algorithm has made a decision about them, and why.",
  "MOD|What about surveillance? Cameras with facial recognition are spreading quickly.",
  "P2|In many cases, citizens are recorded without their consent. Without strong legal safeguards, this technology can easily be misused.",
  "MOD|And autonomous weapons?", "P1|Most ethicists agree that a human must stay in control of any decision to use force.",
  "MOD|Is regulation the answer?", "P2|It's part of the answer. But ethical design has to start with the engineers."],
 [Q("Why can algorithms repeat bias?", "They learn from past data, which may be biased."),
  Q("What do people have a right to know?", "When an algorithm has made a decision about them, and why."),
  Q("What do most ethicists agree about autonomous weapons?", "A human must stay in control of any decision to use force.")],
 [bosluk("YDS köşesi", YDS_TALIMAT, ["Patients must give informed", "before taking part in any clinical trial."],
         ["consent", "surveillance", "transparency", "dilemma", "algorithm"], 0,
         ["T|Klinik bir çalışmaya katılmadan önce hastaların bir şey vermesi gerekiyor.", "T|Kalıp şu: bilgilendirilmiş onay. Doğru cevap:", "E|consent."]),
  konusma("IELTS konuşma köşesi", IELTS3, "Do the benefits of artificial intelligence outweigh the risks?",
          ["I'd say the benefits are enormous, particularly in medicine, where algorithms can detect diseases earlier than doctors.",
           "However, the risks are real, especially when systems are used without transparency or accountability.",
           "For instance, if an algorithm rejects a loan application, people deserve to know why.",
           "So the key is strong safeguards, rather than trying to stop the technology altogether."])],
 konusmacilar={"MOD": "bf_emma", "P1": "am_michael", "P2": "af_heart"},
 dinleme_en=["Imagine a self-driving car that cannot avoid an accident.", "It can either hit a group of pedestrians or swerve and put its passenger at risk.",
             "What should it do?", "This is a modern version of a famous philosophical puzzle known as the trolley problem.",
             "When researchers asked millions of people around the world, the answers varied by culture.",
             "This suggests that there may be no single ethical rule that everyone accepts."],
 dinleme_en_sesi="bf_isabella"),

